"""Siddhidatri `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    d = r["dataset"]
    out = [
        "<!-- Generated by packages/sati/sati/fuse/report.py from the training workflow. Do not edit by hand. -->\n",
        "# Siddhidatri v0 — three detectors, one calibrated verdict\n",
        f"**{d['name']}** ({d['repo']} @ `{d['revision'][:12]}`), {d['machines']} real servers. Siddhidatri is a "
        f"logistic regression over {', '.join(r['fused'])}. Its weights are learned on Shailaputri's *out-of-fold* "
        "scores inside the training groups, so the fusion never trusts a model scored on its own training data. "
        "Each machine group is held out in turn. Each single detector is also given its own logistic "
        "calibration, so every row states a probability.\n",
        "## Mean across held-out machine groups\n",
        "| Verdict from | F1 | Episode recall | False alarms / 1000 | ECE ↓ | Brier ↓ |",
        "|---|---:|---:|---:|---:|---:|",
    ]
    for name, m in r["mean_across_groups"].items():
        label = f"**{name}**" if name.startswith("siddhidatri") else name
        out.append(f"| {label} | {m['f1']:.3f} | {m['recall']:.3f} | {m['false_alarms_per_1000']:.1f} | "
                   f"{m['ece']:.4f} | {m['brier']:.4f} |")
    out += ["", "## Fusion weights per held-out group\n", "| Held out | " + " | ".join(r["fused"]) + " | bias |",
            "|---|" + "---:|" * (len(r["fused"]) + 1)]
    for f in r["folds"]:
        out.append(f"| `{f['held_out']}` | " + " | ".join(f"{f['weights'][k]:+.3f}" for k in [*r["fused"], "bias"]) + " |")
    out += [
        "",
        "## How to read this\n",
        "- **ECE** (expected calibration error) is the average gap between the probability stated and the rate "
        "observed. 0 means a verdict of 80% is right 80% of the time. **Brier** is the mean squared error of the "
        "probabilities.",
        "- A large weight on one detector means the others add little *on these servers*. That is a finding, not "
        "a failure.",
        "- Designed, written and trained by an AI assistant under the owner's direction "
        "([adr/RealDataModels](../../adr/RealDataModels.md)).",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
